(()=>{'use strict';
const definitions=[
['bridge-planks','はしを かけよう','🌉','トラック'],['fuel-match','ガソリン いくつ？','⛽','くるま'],['mirror-bus','かがみの バス','🚌','バス'],['traffic-pause','しんごうで とまろう','🚦','バス'],['repair-wheels','タイヤを なおそう','🛞','トラック'],['tunnel-echo','トンネルの こだま','🚆','でんしゃ'],['delivery-map','にもつを とどけよう','📦','トラック'],['shadow-cloud','くもの かくれんぼ','✈️','ひこうき'],['boat-current','かわの ながれ','🚤','ふね'],['rescue-priority','たすける じゅんばん','🚑','きゅうきゅうしゃ']
];
const game=definitions.find(g=>g[0]===document.body.dataset.game);if(!game)return;
const $=id=>document.getElementById(id),stage=$('stage'),choices=$('choices'),hint=$('hint'),progress=$('progress');
let round=0,question=null,busy=true,epoch=0,ctx=null;
const names={'🏠':'おうち','🏫':'がっこう','🏥':'びょういん','🏪':'おみせ','🏡':'おうち','🚑':'きゅうきゅうしゃ','🚒':'しょうぼうしゃ','🚓':'パトカー','🚁':'ヘリコプター','✈️':'ひこうき','🚀':'ロケット','🛩️':'ちいさな ひこうき','🛸':'ユーエフオー','🔴':'あか','🟢':'あお','🟡':'きいろ','🛑':'とまる','▶️':'すすむ','🐢':'ゆっくり','↩️':'もどる','➡️':'みぎ','⬅️':'ひだり','⬇️':'した','⬆️':'うえ','🟦':'あお','🟨':'きいろ','🟩':'みどり','🟥':'あか','タン':'タン','トン':'トン','ポン':'ポン'};const spoken=DailyQuality.spoken;const pick=a=>a[Math.floor(Math.random()*a.length)],shuffle=a=>[...a].sort(()=>Math.random()-.5),pause=t=>new Promise(r=>setTimeout(r,t));
function unlock(){try{ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume()}catch{}}
function notes(freqs,volume=.02){unlock();if(!ctx)return;freqs.forEach((f,i)=>{const t=ctx.currentTime+i*.11,o=ctx.createOscillator(),v=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(f,t);o.frequency.exponentialRampToValueAtTime(f*1.03,t+.1);v.gain.setValueAtTime(.0001,t);v.gain.exponentialRampToValueAtTime(volume,t+.018);v.gain.exponentialRampToValueAtTime(.0001,t+.19);o.connect(v).connect(ctx.destination);o.start(t);o.stop(t+.2)})}
function cancel(){epoch++;DailyQuality.cancel()}
async function speak(text){return DailyQuality.speak(text)}
function btn(label,fn,spoken=label){const b=document.createElement('button');b.className='choice';b.innerHTML=DailyQuality.markup(label);b.setAttribute('aria-label',DailyQuality.spoken(spoken));b.onclick=fn;choices.append(b)}
function create(){
const r=round,m=game[0],q={prompt:'',view:'',detail:'',options:[],answer:'',feedback:'',sequence:null};
if(m==='bridge-planks'){const n=r+2;q.view='🚚   🟫  🌊'.repeat(1);q.detail='🌉 '+ '〰️'.repeat(n);q.answer='🪵'.repeat(n);q.options=[1,2,3,4,5].map(String);q.answer=String(n);q.prompt='かわに はしを かけよう。 ひつような きは '+n+'ほん だよ。 '+n+'の すうじを おしてね';q.feedback='はしが つながったね'}
if(m==='fuel-match'){const n=r+1;q.view='🚗  ⛽';q.detail='ガソリン '+ '🟩'.repeat(n)+'⬜'.repeat(4-n);q.answer=String(n);q.options=['1','2','3','4'];q.prompt='ガソリンの みどりの めもりを かぞえよう。 '+n+'こ あるね。 '+n+'の すうじを おしてね';q.feedback=n+'めもり いれたね'}
if(m==='mirror-bus'){const shapes=['🟦','🟨','🟩','🟥'];const a=shuffle(shapes).slice(0,r+2),last=pick(a);q.view='🚌  🪞';q.detail=a.join(' ')+' │ '+a.slice().reverse().map(x=>x===last?'❔':x).join(' ');q.answer=last;q.options=shuffle(shapes);q.prompt='かがみの まどが ひとつ かくれたよ。 '+spoken(last)+'の まどを おしてね';q.feedback='かがみが かんせいしたね'}
if(m==='traffic-pause'){const a=[['🔴','とまる','🛑'],['🟢','すすむ','▶️'],['🟡','とまる','🛑']];const x=a[r];q.view='🚌  '+x[0];q.detail='🚦  🛣️';q.answer=x[2];q.options=['🛑','▶️'];q.prompt='しんごうは '+(['あか','あお','きいろ'][r])+'だよ。 '+x[1]+'の マークを おしてね';q.feedback=x[1]+'が できたね'}
if(m==='repair-wheels'){const n=r+1;q.view='🚚  🔧';q.detail='タイヤが '+n+'こ たりないよ  '+'⚪'.repeat(n);q.answer='🛞'.repeat(n);q.options=['1','2','3','4'];q.answer=String(n);q.prompt='トラックの タイヤが '+n+'こ たりないよ。 '+n+'の すうじを おしてね';q.feedback='タイヤが ついたね'}
if(m==='tunnel-echo'){const a=['タン','トン','ポン'];const seq=[a[r]];q.view='🚆  🚇  🔊';q.detail=seq[0];q.sequence=seq;q.answer=seq[0];q.options=shuffle(a);q.prompt='トンネルから '+spoken(seq[0])+'の おとが するよ。 '+spoken(seq[0])+'を おしてね';q.feedback='こだまが きこえたね'}
if(m==='delivery-map'){const a=['🏠','🏫','🏥','🏪'];const seq=shuffle(a).slice(0,r+2);q.view='🚚  🗺️';q.detail=seq.join(' → ');q.sequence=seq;q.answer=seq[0];q.options=[...seq];q.prompt='にもつを じゅんばんに とどけよう。 さいしょは '+spoken(seq[0])+' だよ。 '+spoken(seq[0])+'の マークを おしてね';q.feedback='にもつが とどいたね'}
if(m==='shadow-cloud'){const a=['✈️','🚁','🚀','🛩️','🛸'];const target=a[r];q.view='☁️  ☁️  '+target+'  ☁️';q.detail='くもの なかの のりものを さがそう';q.answer=target;q.options=shuffle(a);q.prompt='くもの あいだに '+spoken(target)+'が いるよ。 '+spoken(target)+'の マークを おしてね';q.feedback='くもの なかに いたね'}
if(m==='boat-current'){const a=[['➡️','みぎ','⛵'],['⬅️','ひだり','🚤'],['⬇️','した','🛶']];const x=a[r];q.view=x[2]+'  🌊  '+x[0];q.detail='ながれに のって すすもう';q.answer=x[0];q.options=shuffle(['➡️','⬅️','⬇️','⬆️']);q.prompt='かわの ながれは '+x[1]+' だね。 '+x[1]+'の やじるしを おしてね';q.feedback='ながれに のれたね'}
if(m==='rescue-priority'){const a=[['🚑','🏥','びょういん'],['🚒','🔥','かじ'],['🚓','🚦','こうさてん']];const x=a[r];q.view=x[1]+'  📣';q.detail='だれを よぼう？';q.answer=x[0];q.options=shuffle(['🚑','🚒','🚓','🚁']);q.prompt=x[2]+'で こまっているよ。 '+spoken(x[0])+'を よぼう。 '+spoken(x[0])+'の マークを おしてね';q.feedback='たすけに きたね'}
q.options=DailyQuality.ordered(q.options);return q}
function draw(){stage.innerHTML='<div class="picture">'+DailyQuality.markup(question.view)+'</div><div class="detail">'+DailyQuality.markup(question.detail)+'</div>';choices.innerHTML='';question.options.forEach(x=>{btn(x,()=>choose(x),spoken(x));choices.lastChild.dataset.value=x});progress.textContent=(round+1)+' / 3'+(question.sequence?'　'+((question.sequenceIndex||0)+1)+' / '+question.sequence.length:'');DailyQuality.state('speaking',round,question.sequenceIndex||0)}
async function begin(){cancel();busy=true;question=create();question.sequenceIndex=0;draw();const e=epoch;await speak(question.prompt);if(epoch===e){busy=false;DailyQuality.state('play',round)}}
function sparkle(){stage.classList.add('success');const s=document.createElement('span');s.className='star';s.textContent='✦ ✦ ✦';stage.append(s);setTimeout(()=>{s.remove();stage.classList.remove('success')},800)}
async function choose(x){if(busy)return;busy=true;unlock();const e=epoch;DailyQuality.state('speaking',round,question.sequenceIndex||0);const b=[...choices.children].find(b=>b.dataset.value===x);if(x!==question.answer){notes([392,440],.012);b?.classList.add('wrong');document.body.dataset.result='retry';await speak('これは '+spoken(x)+' だね。 '+question.prompt);if(e!==epoch)return;b?.classList.remove('wrong');busy=false;DailyQuality.state('play',round,question.sequenceIndex||0);return}
notes([523,659,784]);b?.classList.add('right');sparkle();document.body.dataset.result='correct';if(game[0]==='bridge-planks')stage.querySelector('.detail').innerHTML=DailyQuality.icon('🌉');if(game[0]==='repair-wheels')stage.querySelector('.detail').textContent='● '.repeat(Number(x));await speak('できた！ '+question.feedback);if(e!==epoch)return;
if(question.sequence&&question.sequenceIndex<question.sequence.length-1){question.sequenceIndex++;question.answer=question.sequence[question.sequenceIndex];question.detail=question.sequence.map((v,i)=>i<question.sequenceIndex?'✓':v).join(' → ');question.prompt='つぎは '+spoken(question.answer)+'に とどけよう。 '+spoken(question.answer)+'の マークを おしてね';draw();await speak(question.prompt);if(e!==epoch)return;busy=false;DailyQuality.state('play',round,question.sequenceIndex);return}
round++;if(round<3){await pause(300);if(e===epoch)await begin()}else await finish()}
async function finish(){cancel();busy=true;const e=epoch;DailyQuality.state('complete',3);notes([523,659,784,1046,880,1175],.027);stage.textContent='✦　✦　✦';choices.innerHTML='';progress.textContent='3 / 3';await speak('ぜんぶ できたね！ すごいね！');if(e!==epoch)return;btn('もういちど',()=>{round=0;begin()},'もういちど');btn('ゲームいちらん',()=>location.href='../../index.html','ゲームいちらん');busy=false}
function intro(){cancel();busy=true;question=null;DailyQuality.state('intro',0);stage.innerHTML=DailyQuality.markup(game[2]);const preview=create();hint.textContent=preview.prompt;progress.textContent='あそびかた';choices.innerHTML='';btn('せつめいを きく',()=>{unlock();speak(preview.prompt)},'せつめいを きく');btn('はじめる',()=>{unlock();begin()},'はじめる')}
$('repeat').onclick=async()=>{unlock();if(busy||!question)return;busy=true;const e=epoch;DailyQuality.state('speaking',round,question.sequenceIndex||0);await speak(question.prompt);if(e===epoch){busy=false;DailyQuality.state('play',round,question.sequenceIndex||0)}};$('again').onclick=()=>{round=0;intro()};addEventListener('pagehide',cancel);intro();
})();
